# Two-trough bullish divergence over a 'width' window, then gate.
def bullish_div(price, ind, lower=30, width=20):
    sig = pd.Series(False, index=price.index)
    v=ind.values; p=price.values
    for i in range(len(v)-3*width):
        if v[i] < lower:
            for a in range(i+1, i+width):
                if v[a] > lower:
                    for r in range(a+1, a+width):
                        if v[r]<lower and v[r]>v[i] and p[r]<p[i]:
                            for s in range(r+1, r+width):
                                if v[s]>lower:
                                    sig.iloc[s]=True; break
                            break
                    break
    return sig
