def chande_cmo(close, n=13):
    d = close.diff()
    up = d.clip(lower=0).rolling(n).sum()
    dn = (-d.clip(upper=0)).rolling(n).sum()
    return 100*(up-dn)/(up+dn)

def schaff_stc(close, fast=23, slow=50, cyc=10, d1=3, d2=3):
    m = close.ewm(span=fast,adjust=False).mean() - close.ewm(span=slow,adjust=False).mean()
    def stoch(s,n):
        lo=s.rolling(n).min(); hi=s.rolling(n).max()
        return 100*(s-lo)/(hi-lo).replace(0,1e-9)
    k = stoch(m,cyc).ewm(span=d1,adjust=False).mean()
    stc = stoch(k,cyc).ewm(span=d2,adjust=False).mean()
    return stc  # 0..100

def cci(df, n=20):
    tp = (df['high']+df['low']+df['close'])/3
    sma = tp.rolling(n).mean()
    mad = tp.rolling(n).apply(lambda x: (abs(x-x.mean())).mean(), raw=True)
    return (tp-sma)/(0.015*mad)

def mfi(df, n=14):
    tp=(df['high']+df['low']+df['close'])/3
    rmf=tp*df['volume']
    pos=rmf.where(tp>tp.shift(),0.0).rolling(n).sum()
    neg=rmf.where(tp<tp.shift(),0.0).rolling(n).sum()
    return 100 - 100/(1 + pos/neg.replace(0,1e-9))

def coppock(close, roc1=14, roc2=11, wma=10):
    r = 100*(close/close.shift(roc1)-1) + 100*(close/close.shift(roc2)-1)
    w = pd.Series(range(1,wma+1),dtype=float)
    return r.rolling(wma).apply(lambda x:(x*w.values).sum()/w.sum(), raw=True)
