def mod_fisher(df, n=5):
    lo=df['low'].rolling(n).min(); hi=df['high'].rolling(n).max()
    st=(df['close']-lo)/(hi-lo).replace(0,1e-9)
    x=(2*st-1).clip(-0.999,0.999)
    return 0.5*np.log((1+x)/(1-x))
