def trix(close, n=15):
    e1=close.ewm(span=n,adjust=False).mean()
    e2=e1.ewm(span=n,adjust=False).mean()
    e3=e2.ewm(span=n,adjust=False).mean()
    return 100*e3.diff()/e3.shift()

def elder_ray(df, n=13):
    ema=df['close'].ewm(span=n,adjust=False).mean()
    bull=df['high']-ema
    bear=df['low']-ema
    return bull, bear  # bullish gate: (bull>0)&(bear>0)&(bull>bull.shift())&(bear>bear.shift())

def williams_r(df, n=14):
    hi=df['high'].rolling(n).max(); lo=df['low'].rolling(n).min()
    return -100*(hi-df['close'])/(hi-lo).replace(0,1e-9)  # -100..0; <-80 oversold, >-20 overbought

