# Parabolic SAR run on the RSI series (treat rsi as H=L=C)
def psar(series, af0=0.02, af_step=0.02, af_max=0.2):
    v=series.values; n=len(v); sar=np.full(n,np.nan)
    if n<2: return pd.Series(sar,index=series.index)
    bull=True; af=af0; ep=v[0]; sar[0]=v[0]
    for i in range(1,n):
        prev=sar[i-1]
        cur=prev+af*(ep-prev)
        if bull:
            if v[i]<cur:
                bull=False; cur=ep; ep=v[i]; af=af0
            else:
                if v[i]>ep: ep=v[i]; af=min(af+af_step,af_max)
        else:
            if v[i]>cur:
                bull=True; cur=ep; ep=v[i]; af=af0
            else:
                if v[i]<ep: ep=v[i]; af=min(af+af_step,af_max)
        sar[i]=cur
    return pd.Series(sar,index=series.index)
