import numpy as np
# d: DataFrame with columns close, rsi (14-period). Returns buy/sell flag series.
def kaabar_divergence(d, lb=30, ub=70, width=60):
    c=d['close'].values; r=d['rsi'].values; n=len(d)
    buy=np.zeros(n); sell=np.zeros(n)
    for i in range(n):
        if r[i] < lb:
            for a in range(i+1, min(i+width,n)):
                if r[a] > lb:
                    for rr in range(a+1, min(a+width,n)):
                        if r[rr] < lb and r[rr] > r[i] and c[rr] < c[i]:
                            for s in range(rr+1, min(rr+width,n)):
                                if r[s] > lb:
                                    buy[s]=1; break
                            break
                    break
    for i in range(n):
        if r[i] > ub:
            for a in range(i+1, min(i+width,n)):
                if r[a] < ub:
                    for rr in range(a+1, min(a+width,n)):
                        if r[rr] > ub and r[rr] < r[i] and c[rr] > c[i]:
                            for s in range(rr+1, min(rr+width,n)):
                                if r[s] < ub:
                                    sell[s]=-1; break
                            break
                    break
    return buy, sell  # causal: only uses bars <= s; flag set ON bar s (the re-cross bar)

def kaabar_hidden_divergence(d, lb=30, ub=70, width=60):
    c=d['close'].values; r=d['rsi'].values; n=len(d)
    buy=np.zeros(n); sell=np.zeros(n)
    for i in range(1,n):
        if r[i] < lb and r[i-1] > lb:
            for a in range(i+1, min(i+width,n)):
                if r[a] > lb:
                    for rr in range(a+1, min(a+width,n)):
                        if r[rr] < lb and r[rr] < r[i] and c[rr] > c[i]:
                            for s in range(rr+1, min(rr+width,n)):
                                if r[s] > lb:
                                    buy[min(s+1,n-1)]=1; break
                            break
                    break
    for i in range(1,n):
        if r[i] > ub and r[i-1] < ub:
            for a in range(i+1, min(i+width,n)):
                if r[a] < ub:
                    for rr in range(a+1, min(a+width,n)):
                        if r[rr] > ub and r[rr] > r[i] and c[rr] < c[i]:
                            for s in range(rr+1, min(rr+width,n)):
                                if r[s] < ub:
                                    sell[min(s+1,n-1)]=-1; break
                            break
                    break
    return buy, sell

def stoch_raw(d, k=100):
    ll=d['low'].rolling(k).min(); hh=d['high'].rolling(k).max()
    return 100*(d['close']-ll)/(hh-ll)
