def td_setup(d):
    diff_dn = (d['close'] < d['close'].shift(4)).astype(int)   # buy-setup bar qualifies
    diff_up = (d['close'] > d['close'].shift(4)).astype(int)   # sell-setup bar qualifies
    def run_count(mask):
        out=np.zeros(len(mask)); c=0
        for i,v in enumerate(mask.values):
            c = c+1 if v else 0
            out[i]=c
        return out
    buy_setup = run_count(diff_dn)   # value 1..9+, 9 = buy setup complete
    sell_setup = run_count(diff_up)
    return buy_setup, sell_setup     # causal; flag where buy_setup==9 (long-reversal) / sell_setup==9 (short)

def td_countdown_buy(d):
    n=len(d); cl=d['close'].values; lo=d['low'].values
    flag=np.zeros(n)
    # naive: restart countdown after each buy-setup-9; here standalone qualifying-bar counter
    cnt=0; bars=[]
    for i in range(2,n):
